const SCENE_ID = "hTGtBrMEJCXdW6er";
const TILE_IDS = [
  "Z5yC8obPboz2ZLrf",
  "HpBJdNJt8WNLRz5U"
];
const FIRST_FLOOR_ID = "PRSFmCV18iW5J0Jr";
const ROOF_ID = "QeGYANMpzdBdB1LS";

const token = event.data.token?.document ?? event.data.token;
const scene = game.scenes.get(SCENE_ID);
if (!token || !scene || token.parent?.id !== SCENE_ID) return;

// Only prompt the client responsible for this movement.
const movementUser = token.movement?.user;
if (movementUser && !movementUser.isSelf) return;

function isTileDestroyed(tile) {
  const data =
    tile?.getFlag("theiks-toolbag", "breakableTerrain") ?? {};

  const rawStates = data.states;
  const states = typeof rawStates === "string"
    ? [rawStates]
    : Array.isArray(rawStates)
      ? rawStates
      : rawStates && typeof rawStates === "object"
        ? Object.values(rawStates)
        : [];

  const stateCount = states.filter(
    state => typeof state === "string" && state.trim()
  ).length;

  const stage =
    Number.isInteger(data.stage) && data.stage >= 0
      ? data.stage
      : 0;

  return stage > 0 && stage >= stateCount;
}

function ladderIsAccessible() {
  return TILE_IDS.every(id => {
    const tile = scene.tiles.get(id);
    return tile?.hidden === true || isTileDestroyed(tile);
  });
}

if (!ladderIsAccessible()) return;

const firstFloor = scene.levels.get(FIRST_FLOOR_ID);
const roof = scene.levels.get(ROOF_ID);
const currentLevelId = String(
  token._source?.level ?? token.level ?? ""
);

const destination =
  currentLevelId === FIRST_FLOOR_ID
    ? roof
    : currentLevelId === ROOF_ID
      ? firstFloor
      : null;

if (!destination) return;

const targetElevation = Number(destination.elevation?.bottom);
const updateElevation = game.modules
  .get("theiks-toolbag")
  ?.api?.updateElevation;

if (
  !Number.isFinite(targetElevation) ||
  typeof updateElevation !== "function"
) {
  ui.notifications.warn(
    "Theik's Toolbag level tools are unavailable."
  );
  return;
}

const dialog = new foundry.applications.api.DialogV2({
  window: {
    title: "Climb the ladder?",
    icon: "fa-solid fa-ladder-water"
  },
  classes: ["theiks-toolbag", "level-change-dialog"],
  position: {width: 420},
  modal: false,
  content: `
    <div class="theiks-toolbag level-change-dialog">
      <p>Do you want to climb the ladder?</p>
    </div>
  `,
  buttons: [
    {
      action: "yes",
      label: "Climb",
      icon: "fa-solid fa-ladder-water",
      default: true,
      callback: () => {
        void (async () => {
          try {
            const levelUnchanged =
              String(
                token._source?.level ?? token.level ?? ""
              ) === currentLevelId;

            if (!ladderIsAccessible() || !levelUnchanged) {
              ui.notifications.warn(
                "The ladder is no longer accessible."
              );
              return;
            }

            await updateElevation(
              token,
              targetElevation,
              false, // Falling
              true,  // Change native Level
              true   // Ignore ceilings
            );
          } catch (error) {
            ui.notifications.error(error.message);
            console.error(
              "Harrowstone | Ladder level change failed",
              error
            );
          }
        })();
      }
    },
    {
      action: "no",
      label: "Stay here",
      icon: "fa-solid fa-xmark"
    }
  ]
});

dialog.render({force: true});

